import {TextButton} from '@smart/web-components';
import React from 'react';
import type {AppModel} from '../../../bff/app-model/create-content-model';
import {useTranslations} from '../../../feature-app/hooks';
import {ROUTE} from '../../constants/common';
import {
  useAemModelContext,
  useAppModelContext,
  useFeatureAppEnv,
  useLocale,
  useUserModelContext,
} from '../../hooks';
import styles from './index.module.scss';

interface ButtonsRowProp {
  disablePrimary?: boolean;
}

export const ButtonsRow: React.FC<ButtonsRowProp> = ({
  disablePrimary,
}): React.JSX.Element => {
  const baseClass = `details-form`;
  const {t} = useTranslations();
  const {aemModel} = useAemModelContext();
  const {
    userModel: {userData},
  } = useUserModelContext();
  const {appContextData} = useAppModelContext();
  const {
    aemContent: {
      personalDetails: {personalDetails},
    },
  } = aemModel!;
  const {
    cartModel: {
      addresses: {paymentAddress},
      cartTypeMap,
    },
  } = appContextData as AppModel;
  const {history} = useFeatureAppEnv().featureServices[`s2:history`];
  const {marketId} = useLocale();

  const navigateHome = () => {
    history.push(ROUTE.HOME);
  };

  const defaultBillingAddress =
    paymentAddress || userData.profile?.defaultBillingAddress;

  const disableButton =
    disablePrimary ||
    (defaultBillingAddress &&
      defaultBillingAddress?.country?.isocode !== marketId.toUpperCase());

  /**
   * @ref https://smarteurope.atlassian.net/browse/IBR-14610
   */
  const renderPrevLabelCTA = () => {
    return cartTypeMap.isPCPOnly
      ? t(`pcp.backCTA`)
      : personalDetails.backToShoppingCartBtn;
  };

  return (
    <div className={styles[`${baseClass}__button-row`]}>
      <TextButton
        type="submit"
        variant="primary"
        className={styles[`${baseClass}__button-row__form-submit-button`]}
        disabled={disableButton}
      >
        {personalDetails.continueBtn}
      </TextButton>
      <TextButton
        size="200"
        type="button"
        variant="hyperlink"
        onClick={navigateHome}
        className={styles[`${baseClass}__button-row__link`]}
      >
        {renderPrevLabelCTA()}
      </TextButton>
    </div>
  );
};

